// Generated by scripts/build-madi-games.mjs. Edit source/ instead.
// The MADI AI Universe - Three.js Interactive Hub

let scene, camera, renderer;

let coreGlobe;

let regions = [];

let tooltip = document.getElementById('map-tooltip');


init();



// Expose VibeCodeWorker state
window.gameState = { title: "the-madi-ai-universe", get active() { return typeof gameActive !== "undefined" ? gameActive : true; } };

window.game = window.gameState;


/* fourweird-fullscreen-patch: refit canvas on fullscreen transitions (button/F/dblclick handled in index.html). */
(function () {
  'use strict';
  try {
    function fwRefit() {
      try {
        if (typeof onWindowResize === 'function') { onWindowResize(); }
      } catch (e) {}
      try {
        var fs = !!(document.fullscreenElement || document.webkitFullscreenElement);
        if (document.body) { document.body.classList.toggle('is-fullscreen', fs); }
        var f = document.querySelector('.TEMPLATE-4weird-game-frame');
        if (f) { f.classList.toggle('is-fullscreen', fs); }
      } catch (e) {}
    }
    document.addEventListener('fullscreenchange', fwRefit);
    document.addEventListener('webkitfullscreenchange', fwRefit);
    window.addEventListener('fourweird-fullscreen', fwRefit);
  } catch (e) {}
})();





function init() {
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x06050b);

    camera = new THREE.PerspectiveCamera(60, 800 / 600, 0.1, 100);
    camera.position.set(0, 0, 10);

    const canvas = document.getElementById('TEMPLATE-4weird-gameCanvas');
    renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true });
    renderer.setSize(canvas.clientWidth, canvas.clientHeight);

    // Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xa78bfa, 1);
    dirLight.position.set(5, 10, 5);
    scene.add(dirLight);

    // Core Globe
    const globeGeo = new THREE.SphereGeometry(2.0, 32, 32);
    const globeMat = new THREE.MeshStandardMaterial({
        color: 0x1e1b4b,
        roughness: 0.8,
        wireframe: true
    });
    coreGlobe = new THREE.Mesh(globeGeo, globeMat);
    scene.add(coreGlobe);

    // Spawn 4 Regional Islands
    setupRegions();
    installRegionLinks();

    // Event listeners
    canvas.addEventListener('mousemove', onMouseMove);
    canvas.addEventListener('click', onClick);
    canvas.addEventListener('touchstart', (e) => {
        e.preventDefault();
        const touch = e.touches[0];
        // Simulate mouse move to highlight and then trigger click
        onMouseMove({ clientX: touch.clientX, clientY: touch.clientY });
        onClick({ clientX: touch.clientX, clientY: touch.clientY });
    }, { passive: false });

    window.addEventListener('resize', onWindowResize);
    onWindowResize();

    animate();
}



function setupRegions() {
    const regionGeo = new THREE.CylinderGeometry(0.8, 1.0, 0.4, 6);

    const data = [
        { x: -3.5, y: 1.5, color: 0x10b981, name: 'Revenue Jungle', url: '/games/the-revenue-jungle' },
        { x: 3.5, y: 1.5, color: 0xf59e0b, name: 'Temple of Lost Revenue', url: '/games/temple-of-lost-revenue' },
        { x: -3.5, y: -1.5, color: 0x38bdf8, name: 'Pipeline Mountain', url: '/games/the-pipeline-mountain' },
        { x: 3.5, y: -1.5, color: 0x06b6d4, name: 'Speed Portal', url: '/games/the-speed-portal' }
    ];

    data.forEach(d => {
        const mat = new THREE.MeshPhongMaterial({ color: d.color, shininess: 80 });
        const island = new THREE.Mesh(regionGeo, mat);
        island.position.set(d.x, d.y, 0);
        scene.add(island);
        regions.push({ mesh: island, name: d.name, url: d.url, defaultColor: d.color });
    });
}


function getIntersectedRegion(event) {
    const canvas = renderer.domElement;
    const rect = canvas.getBoundingClientRect();
    const mouse = new THREE.Vector2(
        ((event.clientX - rect.left) / canvas.clientWidth) * 2 - 1,
        -((event.clientY - rect.top) / canvas.clientHeight) * 2 + 1
    );

    const raycaster = new THREE.Raycaster();
    raycaster.setFromCamera(mouse, camera);

    const meshes = regions.map(r => r.mesh);
    const intersects = raycaster.intersectObjects(meshes);

    if (intersects.length > 0) {
        return regions.find(r => r.mesh === intersects[0].object);
    }
    return null;
}



function onMouseMove(event) {
    const intersected = getIntersectedRegion(event);

    regions.forEach(r => {
        r.mesh.material.color.setHex(r.defaultColor);
        r.mesh.scale.set(1.0, 1.0, 1.0);
    });

    if (intersected) {
        intersected.mesh.material.color.setHex(0xffffff); // highlight white
        intersected.mesh.scale.set(1.2, 1.2, 1.2);
        tooltip.textContent = `Warp to: ${intersected.name} (Click to play)`;
    } else {
        tooltip.textContent = 'Hover over a region cylinder to inspect...';
    }
}


function onClick(event) {
    const intersected = getIntersectedRegion(event);
    if (intersected) {
        window.top.location.assign(intersected.url);
    }
}


function onWindowResize() {
    const canvas = document.getElementById('TEMPLATE-4weird-gameCanvas');
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h, false);
}



function animate() {
    requestAnimationFrame(animate);

    // Spin core globe
    coreGlobe.rotation.y += 0.005;

    // Hover effect on islands
    regions.forEach((r, idx) => {
        r.mesh.rotation.y += 0.01;
        r.mesh.position.y = (idx < 2 ? 1.5 : -1.5) + Math.sin(Date.now() * 0.002 + idx) * 0.1;
    });

    renderer.render(scene, camera);
}

// Named links make every destination discoverable without hovering, and let
// keyboard and touch players use the same world selection flow.
function installRegionLinks() {
    const nav = document.createElement('nav');
    nav.setAttribute('aria-label', 'Choose a MADI world');
    Object.assign(nav.style, {
        position: 'absolute', bottom: '48px', left: '12px', right: '12px',
        maxWidth: '440px', margin: '0 auto', display: 'grid',
        gridTemplateColumns: '1fr 1fr', gap: '6px', zIndex: '12'
    });
    for (const region of regions) {
        const link = document.createElement('a');
        link.href = region.url;
        link.target = '_top';
        link.textContent = region.name;
        const color = '#' + region.defaultColor.toString(16).padStart(6, '0');
        Object.assign(link.style, {
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            minHeight: '36px', padding: '4px 8px', borderRadius: '8px',
            border: '1px solid ' + color, color: '#f8fafc', background: '#090a18ed',
            font: '600 12px system-ui', textAlign: 'center', textDecoration: 'none'
        });
        link.addEventListener('focus', () => { tooltip.textContent = 'Enter ' + region.name; });
        nav.appendChild(link);
    }
    Object.assign(tooltip.style, { top: '12px', bottom: 'auto', padding: '8px 12px', maxWidth: '90%', fontSize: '12px' });
    tooltip.textContent = 'Choose a world below or select an island';
    renderer.domElement.parentElement.appendChild(nav);
}
